-- Generated by tools/build_quest_data.py; references are not eligibility or a walkthrough.
return {["scripts/quests/jeuno/Pretty_Little_Things.lua"]={["Path"]="scripts/quests/jeuno/Pretty_Little_Things.lua",["SHA256"]="43c9893b1a07d6c4a231437736c20301c1b9b96bd24b40258dd8c867dfef4dbf",["Text"]="-----------------------------------\n-- Pretty Little Things\n-----------------------------------\n-- Log ID: 3, Quest ID: 43\n-- Zona Shodhun : !pos -175 -5 -4 246\n-----------------------------------\nlocal portJeunoID = zones[xi.zone.PORT_JEUNO]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.JEUNO, xi.quest.id.jeuno.PRETTY_LITTLE_THINGS)\n\nquest.reward =\n{\n}\n\nlocal invalidRocks =\n{\n    xi.item.RED_ROCK,\n    xi.item.BLUE_ROCK,\n    xi.item.GREEN_ROCK,\n    xi.item.TRANSLUCENT_ROCK,\n    xi.item.PURPLE_ROCK,\n    xi.item.BLACK_ROCK,\n    xi.item.WHITE_ROCK,\n}\n\nlocal flowerItems =\n{\n    xi.item.AMARYLLIS,\n    xi.item.ASPHODEL,\n    xi.item.CARNATION,\n    xi.item.CASABLANCA,\n    xi.item.CATTLEYA,\n    xi.item.CHAMOMILE,\n    xi.item.DAHLIA,\n    xi.item.FLAX_FLOWER,\n    xi.item.LILAC,\n    xi.item.LYCOPODIUM_FLOWER,\n    xi.item.MARGUERITE,\n    xi.item.OLIVE_FLOWER,\n    xi.item.PAPAKA_GRASS,\n    xi.item.PHALAENOPSIS,\n    xi.item.RAIN_LILY,\n    xi.item.RED_ROSE,\n    xi.item.SNOW_LILY,\n    xi.item.SWEET_WILLIAM,\n    xi.item.TAHRONGI_CACTUS,\n    xi.item.WATER_LILY,\n}\n\nlocal function isTradeInTable(trade, itemTable)\n    for _, itemID in ipairs(itemTable) do\n        if npcUtil.tradeHasExactly(trade, itemID) then\n            return true\n        end\n    end\n\n    return false\nend\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE or status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.PORT_JEUNO] =\n        {\n            -- Any trade or onTrigger flags this quest.  Default action is handled\n            -- in the NPC script (onTrigger).  All valid items are consumed until\n            -- quest is completed.\n            ['Zona_Shodhun'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, xi.item.YELLOW_ROCK) then\n                        return quest:progressEvent(10023, 1, 246, 2, 1, 0, 1, 5, 1)\n                    elseif isTradeInTable(trade, invalidRocks) then\n                        return quest:progressEvent(10023, 0, 246, 1, 1, 0, 1, 7, 1)\n                    elseif isTradeInTable(trade, flowerItems) then\n                        return quest:progressEvent(10023, 0, 246, 1, 1, 1, 0, 7, 0)\n                    else\n                        return quest:progressEvent(10023, 0, 246, 0, 0, 0, 0, 7, 0)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [10023] = function(player, csid, option, npc)\n                    -- Three possible event options are returned from the above triggers:\n                    -- 0    : Invalid Item was traded\n                    -- 1    : Valid Item was traded\n                    -- 4002 : Yellow Rock was traded\n                    if option > 0 then\n                        player:confirmTrade()\n                    end\n\n                    if option == 4002 then\n                        if quest:complete(player) then\n                            player:confirmTrade()\n                            local mhflag = player:getMoghouseFlag()\n                            player:setMoghouseFlag(mhflag + 0x0008)\n                            player:messageSpecial(portJeunoID.text.MOGHOUSE_EXIT)\n                        end\n                    elseif player:getQuestStatus(quest.areaId, quest.questId) == xi.questStatus.QUEST_AVAILABLE then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.PORT_JEUNO] =\n        {\n            ['Zona_Shodhun'] =\n            {\n                -- NOTE: No items are consumed after quest complete.\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, xi.item.YELLOW_ROCK) then\n                        return quest:progressEvent(10023, 0, 246, 4, 1, 0, 1, 7, 0)\n                    elseif isTradeInTable(trade, invalidRocks) then\n                        return quest:progressEvent(10023, 0, 246, 5, 1, 0, 1, 7, 0)\n                    elseif isTradeInTable(trade, flowerItems) then\n                        return quest:progressEvent(10023, 0, 246, 3, 1, 1, 0, 7, 0)\n                    else\n                        return quest:progressEvent(10023, 0, 246, 5, 0, 0, 0, 7, 0)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/jeuno/Rubbish_Day.lua"]={["Path"]="scripts/quests/jeuno/Rubbish_Day.lua",["SHA256"]="48ca6acaca82d755b9c31e2842365ddbc257b1b40b6505b60c733449f5d68949",["Text"]="-----------------------------------\n-- Rubbish Day\n-----------------------------------\n-- Log ID: 3, Quest ID: 13\n-- Chululu : !pos -13 -6 -42 245\n-- Mashira : !pos 141 -6 138 200\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.JEUNO, xi.quest.id.jeuno.RUBBISH_DAY)\n\nquest.reward =\n{\n    gil  = 6000,\n    item = xi.item.CHAIN_CHOKER,\n}\n\nlocal compatibilityReplies =\n{\n    DEFAULT     = 0, --  Used for a valid partner; 'Your partner doesn't seem to be nearby.' when no partner is matched.\n    CHULULU     = 1, -- 'What? With me!? Spare me.'\n    KUROU_MOROU = 2, -- 'What? With that creep? Over my dead body!'\n    EMPTY       = 3, -- 'Please fill in your partner's name.'\n}\n\n-- TODO: Returned bits may be based off of name or other factors. Requires significant captures. For now, this is one of each reply, chosen randomly.\nlocal eventBits =\n{\n    { 4, 3, 5, 8, 2, 2, 0, 0 },\n    { 4, 3, 5, 8, 1, 2, 0, 0 },\n    { 2, 1, 0, 0, 0, 1, 0, 0 },\n    { 3, 1, 0, 0, 0, 1, 0, 0 },\n    { 8, 3, 1, 1, 1, 2, 1, 0 },\n    { 8, 3, 5, 8, 2, 1, 1, 0 },\n}\n\n-- Resolves a typed partner name to (matchedId, reply) for the compatibility reading.\nlocal function checkCompatibilityString(player, name)\n    if name == '' then\n        return 0, compatibilityReplies.EMPTY\n    end\n\n    local input = string.lower(name)\n\n    if input == 'chululu' then\n        return 0, compatibilityReplies.CHULULU\n    elseif input == 'kurou-morou' then\n        return 0, compatibilityReplies.KUROU_MOROU\n    end\n\n    local partner = GetPlayerByName(name)\n\n    if\n        partner and\n        partner:getID() ~= player:getID() and\n        partner:getZoneID() == player:getZoneID()\n    then\n        return partner:getID(), compatibilityReplies.DEFAULT\n    end\n\n    return 0, compatibilityReplies.DEFAULT\nend\n\n-- Compatibility reading (event 199). Players may continue to get readings even after the quest is offered / completed.\nlocal function onCompatibilityUpdate(player, option, countReading)\n    if type(option) == 'string' then\n        player:updateEvent(player:getID(), checkCompatibilityString(player, option))\n\n    elseif option ~= 0 then\n        local partner = GetPlayerByID(option)\n\n        if\n            partner and\n            partner:getZoneID() == player:getZoneID()\n        then\n            if\n                countReading and\n                quest:getVar(player, 'Day') ~= VanadielUniqueDay()\n            then\n                quest:setVar(player, 'Prog', quest:getVar(player, 'Prog') + 1)\n                quest:setVar(player, 'Day', VanadielUniqueDay())\n            end\n\n            player:updateEvent(unpack(eventBits[math.randomInt(1, #eventBits)]))\n        end\n    end\nend\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getQuestStatus(xi.questLog.JEUNO, xi.quest.id.jeuno.COLLECT_TARUT_CARDS) == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.LOWER_JEUNO] =\n        {\n            ['Chululu'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        quest:getVar(player, 'Prog') >= 3 and\n                        quest:getVar(player, 'Day') ~= VanadielUniqueDay()\n                    then\n                        return quest:progressEvent(198) -- Offers the quest\n                    else\n                        return quest:progressEvent(199) -- Compatibility test; first completed reading each day counts, but can get unlimited readings until you are offered the quest.\n                    end\n                end,\n            },\n\n            onEventUpdate =\n            {\n                [199] = function(player, csid, option, npc)\n                    onCompatibilityUpdate(player, option, true)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [198] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:begin(player)\n                        npcUtil.giveKeyItem(player, xi.keyItem.MAGIC_TRASH)\n                        quest:setVar(player, 'Prog', 0)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.LOWER_JEUNO] =\n        {\n            ['Chululu'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 1 then\n                        return quest:progressEvent(197) -- Finishes the quest\n                    else\n                        return quest:event(49) -- Reminder\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [197] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:addFame(xi.fameArea.SANDORIA, 13)\n                        player:addFame(xi.fameArea.BASTOK, 13)\n                        player:addFame(xi.fameArea.WINDURST, 13)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.GARLAIGE_CITADEL] =\n        {\n            ['Mashira'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 0 then\n                        return quest:progressEvent(11, 1)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [11] = function(player, csid, option, npc)\n                    if option == 1 then\n                        player:delKeyItem(xi.keyItem.MAGIC_TRASH)\n                        quest:setVar(player, 'Prog', 1)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.LOWER_JEUNO] =\n        {\n            ['Chululu'] = quest:event(199), -- Compatibility can be tested even after completing the quest. (Cycles with her other dialog)\n\n            onEventUpdate =\n            {\n                [199] = function(player, csid, option, npc)\n                    onCompatibilityUpdate(player, option, false)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/jeuno/Save_My_Sister.lua"]={["Path"]="scripts/quests/jeuno/Save_My_Sister.lua",["SHA256"]="6954237ba95ffe7171782527a1bfdb98998a2e1fca656c573385686022c118f5",["Text"]="-----------------------------------\n-- Save My Sister\n-----------------------------------\n-- Log ID: 3, Quest ID: 1\n-- Baudin        : !pos -75 0 80 244\n-- Mailloquetat  : !pos -31 -1 8 244\n-- Neraf-Najiruf : !pos -36 2 60 243\n-- Brazier (F-9) : !pos 101 -33 -59 195\n-- Brazier (H-7) : !pos 259 -33 99 195\n-- Brazier (F-7) : !pos 99 -33 98 195\n-- Brazier (H-9) : !pos 259 -33 -58 195\n-----------------------------------\nlocal eldiemeID = zones[xi.zone.THE_ELDIEME_NECROPOLIS]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.JEUNO, xi.quest.id.jeuno.SAVE_MY_SISTER)\n\nquest.reward =\n{\n    gil   = 3000,\n    item  = xi.item.HOLY_MACE,\n    title = xi.title.EXORCIST_IN_TRAINING,\n}\n\nlocal brazierMessages =\n{\n    [0] = { eldiemeID.text.THE_LIGHT_DIMLY,           eldiemeID.text.REFUSE_TO_LIGHT  },\n    [1] = { eldiemeID.text.THE_LIGHT_HAS_INTENSIFIED, eldiemeID.text.LANTERN_GOES_OUT },\n    [2] = { eldiemeID.text.THE_LIGHT_HAS_INTENSIFIED, eldiemeID.text.LANTERN_GOES_OUT },\n    [3] = { eldiemeID.text.THE_LIGHT_IS_FULLY_LIT,    eldiemeID.text.LANTERN_GOES_OUT },\n}\n\n-- NOTE: This quest does not appear in the player's quest log until it has been completed.\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.JEUNO, xi.quest.id.jeuno.CREST_OF_DAVOI) and\n                player:getFameLevel(xi.fameArea.JEUNO) >= 4\n        end,\n\n        [xi.zone.UPPER_JEUNO] =\n        {\n            ['Baudin'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 0 then\n                        return quest:progressEvent(172)\n                    elseif questProgress == 1 then\n                        return quest:progressEvent(105)\n                    elseif questProgress == 3 then\n                        return quest:event(27)\n                    elseif questProgress == 4 then\n                        return quest:progressEvent(107)\n                    end\n                end,\n            },\n\n            ['Mailloquetat'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 0 then\n                        return quest:progressEvent(159)\n                    else\n                        return quest:event(158)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [105] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n\n                [107] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:addFame(xi.fameArea.SANDORIA, 13)\n                        player:addFame(xi.fameArea.BASTOK, 13)\n                        player:addFame(xi.fameArea.WINDURST, 13)\n                    end\n                end,\n\n                [159] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n\n                [172] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n        },\n\n        [xi.zone.RULUDE_GARDENS] =\n        {\n            ['Neraf-Najiruf'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 2 then\n                        return quest:progressEvent(98)\n                    elseif questProgress >= 3 then\n                        return quest:event(99)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [98] = function(player, csid, option, npc)\n                    if option == 0 then\n                        npcUtil.giveKeyItem(player, xi.keyItem.DUCAL_GUARDS_LANTERN)\n                        quest:setVar(player, 'Prog', 3)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.THE_ELDIEME_NECROPOLIS] =\n        {\n            ['Brazier'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 3 then\n                        return quest:progressEvent(44)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [44] = function(player, csid, option, npc)\n                    if option == 0 then\n                        local lanternStage  = quest:getVar(player, 'Stage')\n                        local lanternOffset = npc:getID() - eldiemeID.npc.BRAZIER\n\n                        if lanternStage == lanternOffset then\n                            player:messageSpecial(brazierMessages[lanternStage][1], 0, 0, 0, xi.keyItem.DUCAL_GUARDS_LANTERN_LIT)\n\n                            if lanternStage < 3 then\n                                quest:incrementVar(player, 'Stage', 1)\n                            else\n                                quest:setVar(player, 'Prog', 4)\n                            end\n                        else\n                            player:messageSpecial(brazierMessages[lanternStage][2], 0, 0, 0, xi.keyItem.DUCAL_GUARDS_LANTERN_LIT)\n                            quest:setVar(player, 'Stage', 0)\n                        end\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.UPPER_JEUNO] =\n        {\n            ['Baudin'] = quest:event(176):replaceDefault(),\n        },\n\n        [xi.zone.RULUDE_GARDENS] =\n        {\n            ['Neraf-Najiruf'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.DUCAL_GUARDS_LANTERN) then\n                        return quest:progressEvent(97)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [97] = function(player, csid, option, npc)\n                    player:delKeyItem(xi.keyItem.DUCAL_GUARDS_LANTERN)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/jeuno/Save_My_Son.lua"]={["Path"]="scripts/quests/jeuno/Save_My_Son.lua",["SHA256"]="071e8f26e84ee09fb7af218cf7f9f6223e06c644494c5beeeabf2cb04241b30a",["Text"]="-----------------------------------\n-- Save My Son\n-----------------------------------\n-- Log ID: 3, Quest ID: 5\n-- Door: Merchant's House (_6t2) : !pos -82.22 -7.65 -168.839 245\n-- Nightflowers                  : !pos -264.775 -3.718 28.767 126\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.JEUNO, xi.quest.id.jeuno.SAVE_MY_SON)\n\nquest.reward =\n{\n    gil      = 2100,\n    item     = xi.item.BEAST_WHISTLE,\n    title    = xi.title.LIFE_SAVER,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.JEUNO, xi.quest.id.jeuno.CHOCOBOS_WOUNDS) and\n                player:getMainLvl() >= xi.settings.main.ADVANCED_JOB_LEVEL\n        end,\n\n        [xi.zone.LOWER_JEUNO] =\n        {\n            ['_6t2'] = quest:progressEvent(164),\n\n            onEventFinish =\n            {\n                [164] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.LOWER_JEUNO] =\n        {\n            ['_6t2'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 1 then\n                        return quest:progressEvent(163)\n                    else\n                        return quest:event(229)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [163] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:addFame(xi.fameArea.SANDORIA, 7)\n                        player:addFame(xi.fameArea.BASTOK, 7)\n                        player:addFame(xi.fameArea.WINDURST, 7)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.UPPER_JEUNO] =\n        {\n            ['Shalott'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 0 then\n                        return quest:event(101)\n                    else\n                        return quest:event(44)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.QUFIM_ISLAND] =\n        {\n            ['Nightflowers'] =\n            {\n                onTrigger = function(player, npc)\n                    local vanadielClockTime = utils.vanadielClockTime()\n\n                    if\n                        quest:getVar(player, 'Prog') == 0 and\n                        (\n                            vanadielClockTime > 2130 or\n                            vanadielClockTime <= 540\n                        )\n                    then\n                        return quest:progressEvent(0)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [0] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.LOWER_JEUNO] =\n        {\n            ['_6t2'] = quest:event(132):replaceDefault(),\n        },\n\n        [xi.zone.UPPER_JEUNO] =\n        {\n            ['Shalott'] = quest:event(44):replaceDefault(),\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED and\n                not player:hasCompletedQuest(xi.questLog.JEUNO, xi.quest.id.jeuno.PATH_OF_THE_BEASTMASTER)\n        end,\n\n        [xi.zone.UPPER_JEUNO] =\n        {\n            ['Chocobo'] = quest:event(55),\n            ['Osker']   = quest:event(55),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/jeuno/Save_the_Clock_Tower.lua"]={["Path"]="scripts/quests/jeuno/Save_the_Clock_Tower.lua",["SHA256"]="89858f07aec9152d865f273d7f456e1abb45320b89727e012511aad8f1c2b464",["Text"]="-----------------------------------\n-- Save the Clock Tower\n-----------------------------------\n-- Log ID: 3, Quest ID: 3\n-- Derrick : !pos -32 -1 -7 245\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.JEUNO, xi.quest.id.jeuno.SAVE_THE_CLOCK_TOWER)\n\nquest.reward =\n{\n    title    = xi.title.CLOCK_TOWER_PRESERVATIONIST,\n}\n\nlocal petitionNpcData =\n{\n    ['Pitantimand']     = { 0,  64 }, -- !pos -63 8 46 246\n    ['Teigero-Bangero'] = { 1,  74 }, -- !pos -58 0 -143 245\n    ['Zauko']           = { 2,  50 }, -- !pos -3 0 11 245\n    ['Baudin']          = { 3, 177 }, -- !pos -75 0 80 244\n    ['Collet']          = { 4, 115 }, -- !pos -44 0 107 244\n    ['Constance']       = { 5, 180 }, -- !pos -48 0 4 244\n    ['Monberaux']       = { 6,  91 }, -- !pos -43 0 -1 244\n    ['Souren']          = { 7, 182 }, -- !pos -51 0 4 244\n    ['Zuber']           = { 8, 126 }, -- !pos -106 0 90 244\n    ['Radeivepart']     = { 9, 160 }, -- !pos 5 9 -39 243\n}\n\nlocal petitionOnTrade = function(player, npc, trade)\n    local npcData = petitionNpcData[npc:getName()]\n\n    if\n        npcUtil.tradeHasExactly(trade, xi.item.CLOCK_TOWER_PETITION) and\n        not quest:isVarBitsSet(player, 'Prog', npcData[1])\n    then\n        return quest:progressEvent(npcData[2], 9 - utils.mask.countBits(quest:getVar(player, 'Prog')))\n    end\nend\n\nlocal petitionNpc =\n{\n    onTrade = petitionOnTrade,\n}\n\nlocal petitionOnEventFinish = function(player, csid, option, npc)\n    quest:setVarBit(player, 'Prog', petitionNpcData[npc:getName()][1])\nend\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.JEUNO, xi.quest.id.jeuno.A_CLOCK_MOST_DELICATE) and\n                player:getFameLevel(xi.fameArea.JEUNO) >= 5\n        end,\n\n        [xi.zone.LOWER_JEUNO] =\n        {\n            ['Derrick'] =\n            {\n                onTrigger = function(player, npc)\n                    local hasAirshipPass = player:hasKeyItem(xi.keyItem.AIRSHIP_PASS) and 2 or 0\n\n                    return quest:progressEvent(230, 8 + hasAirshipPass, 10)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [230] = function(player, csid, option, npc)\n                    if\n                        option == 20 and\n                        npcUtil.giveItem(player, xi.item.CLOCK_TOWER_PETITION)\n                    then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.UPPER_JEUNO] =\n        {\n            ['Collet'] = quest:event(164),\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.LOWER_JEUNO] =\n        {\n            ['Derrick'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        npcUtil.tradeHasExactly(trade, xi.item.CLOCK_TOWER_PETITION) and\n                        utils.mask.countBits(quest:getVar(player, 'Prog')) == 10\n                    then\n                        return quest:progressEvent(231)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    local hasAirshipPass = player:hasKeyItem(xi.keyItem.AIRSHIP_PASS) and 2 or 0\n\n                    return quest:progressEvent(230, 4 + hasAirshipPass, 10)\n                end,\n            },\n\n            ['Teigero-Bangero'] = petitionNpc,\n            ['Zauko']           = petitionNpc,\n\n            onEventFinish =\n            {\n                [50] = petitionOnEventFinish,\n                [74] = petitionOnEventFinish,\n\n                [230] = function(player, csid, option, npc)\n                    -- TODO: Verify if petition should be reset if the player still has one\n                    -- in their inventory.\n\n                    if\n                        option == 30 and\n                        npcUtil.giveItem(player, xi.item.CLOCK_TOWER_PETITION)\n                    then\n                        quest:setVar(player, 'Prog', 0)\n                    end\n                end,\n\n                [231] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:addFame(xi.fameArea.SANDORIA, 17)\n                        player:addFame(xi.fameArea.BASTOK, 17)\n                        player:addFame(xi.fameArea.WINDURST, 17)\n                        player:confirmTrade()\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.PORT_JEUNO] =\n        {\n            ['Pitantimand'] = petitionNpc,\n\n            onEventFinish =\n            {\n                [64] = petitionOnEventFinish,\n            },\n        },\n\n        [xi.zone.UPPER_JEUNO] =\n        {\n            ['Baudin']    = petitionNpc,\n            ['Collet']    = petitionNpc,\n            ['Constance'] = petitionNpc,\n            ['Monberaux'] = petitionNpc,\n            ['Zuber']     = petitionNpc,\n\n            ['Souren'] =\n            {\n                onTrade   = petitionOnTrade,\n                onTrigger = quest:event(120),\n            },\n\n            onEventFinish =\n            {\n                [ 91] = petitionOnEventFinish,\n                [115] = petitionOnEventFinish,\n                [126] = petitionOnEventFinish,\n                [177] = petitionOnEventFinish,\n                [180] = petitionOnEventFinish,\n                [182] = petitionOnEventFinish,\n            },\n        },\n\n        [xi.zone.RULUDE_GARDENS] =\n        {\n            ['Radeivepart'] = petitionNpc,\n\n            onEventFinish =\n            {\n                [160] = petitionOnEventFinish,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.UPPER_JEUNO] =\n        {\n            ['Souren'] = quest:event(181):replaceDefault(),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/jeuno/Scattered_into_Shadow.lua"]={["Path"]="scripts/quests/jeuno/Scattered_into_Shadow.lua",["SHA256"]="6d98cea82ea1b5d8326656f834f895f2a8f030ac2a16b848f7c66a6fe10642ea",["Text"]="-----------------------------------\n-- Scattered into the Shadow\n-----------------------------------\n-- Log ID: 3, Quest ID: 61\n-- Brutus                  !pos -55 8 95 244\n-- Underground Pool Offset !pos 10 0 250 151\n-- Castle_Oztroja Chest    !pos 7 -16 -193 151\n-- Tebhi                   !pos -136 24 -21 151\n-----------------------------------\nlocal upperJeunoID = zones[xi.zone.UPPER_JEUNO]\nlocal feiyinID     = zones[xi.zone.FEIYIN]\nlocal castleOzID   = zones[xi.zone.CASTLE_OZTROJA]\n-----------------------------------\nlocal quest = Quest:new(xi.questLog.JEUNO, xi.quest.id.jeuno.SCATTERED_INTO_SHADOW)\n\nquest.reward =\n{\n    item     = xi.item.BEAST_GAITERS,\n}\n\nlocal function beginQuest(player)\n    quest:begin(player)\n    player:addKeyItem(xi.keyItem.AQUAFLORA1)\n    player:addKeyItem(xi.keyItem.AQUAFLORA2)\n    player:addKeyItem(xi.keyItem.AQUAFLORA3)\nend\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.JEUNO, xi.quest.id.jeuno.WINGS_OF_GOLD) and\n                player:getMainLvl() >= xi.settings.main.AF2_QUEST_LEVEL and\n                player:getMainJob() == xi.job.BST\n        end,\n\n        [xi.zone.UPPER_JEUNO] =\n        {\n            ['Brutus'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 1 then\n                        return quest:progressEvent(143) -- (Short dialog)\n                    else\n                        return quest:progressEvent(141) -- (Long dialog)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [143] = function(player, csid, option, npc)\n                    if option == 1 then\n                        beginQuest(player)\n                        player:messageSpecial(upperJeunoID.text.YOU_ARE_GIVEN_THREE_SPRIGS, xi.keyItem.AQUAFLORA1)\n                    end\n                end,\n\n                [141] = function(player, csid, option, npc)\n                    if option == 1 then\n                        beginQuest(player)\n                        player:messageSpecial(upperJeunoID.text.YOU_ARE_GIVEN_THREE_SPRIGS, xi.keyItem.AQUAFLORA1)\n                    else\n                        quest:setVar(player, 'Prog', 1)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.FEIYIN] =\n        {\n            ['Underground_Pool'] =\n            {\n                onTrigger = function(player, npc)\n                    local offset = npc:getID() - feiyinID.npc.UNDERGROUND_POOL_OFFSET\n\n                    if\n                        offset == 0 and\n                        player:hasKeyItem(xi.keyItem.AQUAFLORA2)\n                    then\n                        return quest:progressEvent(20)\n                    elseif offset == 1 then\n                        if quest:getVar(player, 'Prog') == 2 then\n                            return quest:progressEvent(18)\n                        elseif\n                            player:hasKeyItem(xi.keyItem.AQUAFLORA3) and\n                            npcUtil.popFromQM(player, npc, feiyinID.mob.DABOTZS_GHOST, { claim = true, hide = 0 })\n                        then\n                            return quest:noAction()\n                        end\n                    elseif\n                        offset == 2 and\n                        player:hasKeyItem(xi.keyItem.AQUAFLORA1)\n                    then\n                        return quest:progressEvent(21)\n                    end\n                end,\n            },\n\n            ['Dabotzs_Ghost'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    if player:hasKeyItem(xi.keyItem.AQUAFLORA3) then\n                        quest:setVar(player, 'Prog', 2)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [18] = function(player, csid, option, npc)\n                    player:delKeyItem(xi.keyItem.AQUAFLORA3)\n                    quest:setVar(player, 'Prog', 3)\n                    quest:setVarBit(player, 'Stage', 2)\n                end,\n\n                [20] = function(player, csid, option, npc)\n                    player:delKeyItem(xi.keyItem.AQUAFLORA2)\n                    quest:setVarBit(player, 'Stage', 1)\n                end,\n\n                [21] = function(player, csid, option, npc)\n                    player:delKeyItem(xi.keyItem.AQUAFLORA1)\n                    quest:setVarBit(player, 'Stage', 0)\n                end,\n            },\n        },\n\n        [xi.zone.CASTLE_OZTROJA] =\n        {\n            ['Tebhi'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        npc:getStatus() == xi.status.NORMAL and\n                        npcUtil.tradeHasExactly(trade, xi.item.BEAST_COLLAR)\n                    then\n                        player:tradeComplete()\n                        quest:setVar(player, 'Prog', 5)\n\n                        -- Tebhi stops and faces the player when traded, then fades away.\n                        npc:clearPath(true)\n                        npc:facePlayer(player, false)\n                        npc:setLocalVar('respawnTime', GetSystemTime() + 180)\n                        npc:timer(2000, function(npcArg)\n                            npcArg:entityAnimationPacket(xi.animationString.STATUS_DISAPPEAR)\n                        end)\n\n                        npc:timer(4000, function(npcArg)\n                            npcArg:setStatus(xi.status.CUTSCENE_ONLY)\n                            npcArg:continuePath()\n                        end)\n\n                        return quest:messageSpecial(castleOzID.text.TEBHI_ACCEPTS, xi.item.BEAST_COLLAR)\n                    end\n                end,\n            },\n\n            ['Treasure_Chest' ] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        quest:getVar(player, 'Prog') == 4 and\n                        quest:getVar(player, 'Stage') == 7 and\n                        not player:hasItem(xi.item.BEAST_COLLAR)\n                    then\n                        xi.treasure.onTrade(player, npc, trade, 1, xi.item.BEAST_COLLAR)\n\n                        return quest:noAction()\n                    end\n                end,\n            },\n\n            onZoneIn = function(player, prevZone)\n                -- Tebhi only spawns if a player on this part of the quest zones in.\n                if quest:getVar(player, 'Prog') ~= 4 then\n                    return\n                end\n\n                local tebhi = GetNPCByID(castleOzID.npc.TEBHI)\n\n                if not tebhi then\n                    return\n                end\n\n                -- Attach a listener to each player to ensure Tebhi reappears if multiple people are on the quest.\n                -- Listener cleans up when player zones out or progresses past this step.\n                player:addListener('TICK', 'TEBHI_RESPAWN', function(playerArg)\n                    -- Not in the zone anymore, or not on this step - clean up listener and return.\n                    if\n                        playerArg:getZoneID() ~= xi.zone.CASTLE_OZTROJA or\n                        quest:getVar(playerArg, 'Prog') ~= 4\n                    then\n                        playerArg:removeListener('TEBHI_RESPAWN')\n                        return\n                    end\n\n                    -- Tebhi is already up, return.\n                    if tebhi:getStatus() == xi.status.NORMAL then\n                        return\n                    end\n\n                    -- Not time to respawn Tebhi, return.\n                    if GetSystemTime() < tebhi:getLocalVar('respawnTime') then\n                        return\n                    end\n\n                    -- If we make it here, spawn Tebhi.\n                    tebhi:setStatus(xi.status.NORMAL)\n                    tebhi:entityAnimationPacket(xi.animationString.STATUS_VISIBLE)\n                end)\n            end,\n        },\n\n        [xi.zone.UPPER_JEUNO] =\n        {\n            ['Brutus'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        player:hasKeyItem(xi.keyItem.AQUAFLORA1) or\n                        player:hasKeyItem(xi.keyItem.AQUAFLORA2) or\n                        player:hasKeyItem(xi.keyItem.AQUAFLORA3)\n                    then\n                        return quest:event(142)\n                    elseif quest:getVar(player, 'Prog') == 3 then\n                        return quest:progressEvent(144)\n                    elseif quest:getVar(player, 'Prog') == 4 then\n                        return quest:event(149)\n                    elseif quest:getVar(player, 'Prog') == 5 then\n                        return quest:progressEvent(135)\n                    end\n                end,\n            },\n\n            ['Osker'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 4 then\n                        return quest:event(145)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [135] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:addFame(xi.fameArea.SANDORIA, 7)\n                        player:addFame(xi.fameArea.BASTOK, 7)\n                        player:addFame(xi.fameArea.WINDURST, 7)\n                    end\n                end,\n\n                [144] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 4)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.UPPER_JEUNO] =\n        {\n            ['Brutus'] = quest:event(151):importantOnce(),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/jeuno/Searching_for_the_Right_Words.lua"]={["Path"]="scripts/quests/jeuno/Searching_for_the_Right_Words.lua",["SHA256"]="784e21a24dd442f3ef943297f8de04f23bba7365d11f600f49c62b357ce43956",["Text"]="-----------------------------------\n-- Searching for the Right Words\n-----------------------------------\n-- Log ID: 3, Quest ID: 66\n-- Kurou-Morou : !pos -4 -6 -28 245\n-- Chululu     : !pos -13 -6 -42 245\n-- Ilumida     : !pos -75 -1 58 244\n-- qm2 (???)   : !pos 34.651 -20.183 -61.647 153\n-----------------------------------\nlocal boyahdaID = zones[xi.zone.THE_BOYAHDA_TREE]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.JEUNO, xi.quest.id.jeuno.SEARCHING_FOR_THE_RIGHT_WORDS)\n\nquest.reward =\n{\n    gil  = 3000,\n    item = xi.item.SCROLL_OF_SLEEPGA_II,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.JEUNO, xi.quest.id.jeuno.A_CANDLELIGHT_VIGIL) and\n                player:hasCompletedQuest(xi.questLog.JEUNO, xi.quest.id.jeuno.RUBBISH_DAY) and\n                player:hasCompletedQuest(xi.questLog.JEUNO, xi.quest.id.jeuno.NEVER_TO_RETURN) and\n                player:getFameLevel(xi.fameArea.JEUNO) >= 6 and\n                not quest:getMustZone(player)\n        end,\n\n        [xi.zone.LOWER_JEUNO] =\n        {\n            ['Kurou-Morou'] =\n            {\n                onTrigger = function(player, npc)\n                    local progress = quest:getVar(player, 'Prog')\n\n                    if progress == 0 then\n                        return quest:progressEvent(17) -- Runga-Kopunga visits, Kurou-Morou asks for advice\n                    elseif progress == 1 then\n                        return quest:event(38) -- 'Oh, what should I do!?'\n                    elseif progress == 2 then\n                        return quest:event(36) -- Hint about the moonlight in the Boyahda Tree\n                    end\n                end,\n            },\n\n            ['Chululu'] =\n            {\n                onTrigger = function(player, npc)\n                    local progress = quest:getVar(player, 'Prog')\n\n                    if\n                        progress == 1 or\n                        progress == 2\n                    then\n                        return quest:event(57) -- 'Oh, what should I do...?'\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [17] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:setVar(player, 'Prog', 1)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.UPPER_JEUNO] =\n        {\n            ['Ilumida'] =\n            {\n                onTrigger = function(player, npc)\n                    local progress = quest:getVar(player, 'Prog')\n\n                    if progress == 1 then\n                        return quest:progressEvent(197) -- Quest offered.\n                    elseif progress == 2 then\n                        return quest:progressEvent(201) -- Quest offered again. (Happens if you decline initially)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [197] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:begin(player)\n                        quest:setVar(player, 'Prog', 3)\n                    elseif option == 0 then\n                        quest:setVar(player, 'Prog', 2)\n                    end\n                end,\n\n                [201] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:begin(player)\n                        quest:setVar(player, 'Prog', 3)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.LOWER_JEUNO] =\n        {\n            ['Kurou-Morou'] = quest:event(39), -- 'You've got to go to the Boyahda Tree and get that moondrop!'\n            ['Chululu']     = quest:event(57), -- 'Oh, what should I do...?'\n        },\n\n        [xi.zone.UPPER_JEUNO] =\n        {\n            ['Ilumida'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.MOONDROP) then\n                        return quest:progressEvent(198) -- Quest complete\n                    else\n                        return quest:event(199) -- Reminder\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [198] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.MOONDROP)\n                        player:addFame(xi.fameArea.SANDORIA, 23)\n                        player:addFame(xi.fameArea.BASTOK, 23)\n                        player:addFame(xi.fameArea.WINDURST, 23)\n                        quest:setVar(player, 'Post', 1)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.THE_BOYAHDA_TREE] =\n        {\n            ['qm2'] =\n            {\n                onTrigger = function(player, npc)\n                    local currentHour = VanadielHour()\n\n                    if getVanadielMoonCycle() == xi.moonCycle.NEW_MOON then\n                        return\n                    end\n\n                    if\n                        currentHour < 19 and\n                        currentHour >= 4\n                    then\n                        return\n                    end\n\n                    if player:hasKeyItem(xi.keyItem.MOONDROP) then\n                        return\n                    end\n\n                    local agas = GetMobByID(boyahdaID.mob.AGAS)\n                    if not agas then\n                        return\n                    end\n\n                    if agas:isSpawned() then\n                        return\n                    end\n\n                    local progress = quest:getVar(player, 'Prog')\n\n                    if progress == 4 then\n                        return quest:progressEvent(14) -- Agas defeated, obtain the Moondrop\n                    elseif progress == 3 then\n                        SpawnMob(boyahdaID.mob.AGAS):updateClaim(player) -- Spawn Agas\n                        return quest:messageSpecial(boyahdaID.text.SOMETHING_NOT_RIGHT):replaceDefault()\n                    end\n                end,\n            },\n\n            ['Agas'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    if quest:getVar(player, 'Prog') == 3 then\n                        quest:setVar(player, 'Prog', 4)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [14] = function(player, csid, option, npc)\n                    if\n                        option == 0 and\n                        npcUtil.giveKeyItem(player, xi.keyItem.MOONDROP)\n                    then\n                        quest:setVar(player, 'Prog', 5)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.LOWER_JEUNO] =\n        {\n            ['Kurou-Morou'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Post') == 1 then\n                        return quest:progressEvent(154) -- Kurou-Morou confesses to Chululu\n                    else\n                        return quest:event(37) -- 'So, do you think she understood how I feel?'\n                    end\n                end,\n            },\n\n            ['Chululu'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Post') == 0 then\n                        return quest:event(56) -- 'Boy, was I surprised when he told me he...'\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [154] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:setVar(player, 'Post', 0)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.UPPER_JEUNO] =\n        {\n            ['Ilumida'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Post') == 0 then\n                        return quest:event(196):replaceDefault() -- 'Our little friend was able to express his feelings?'\n                    else\n                        return quest:event(200):replaceDefault() -- 'Thank you again for all of your help.'\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/jeuno/Shadows_of_the_Departed.lua"]={["Path"]="scripts/quests/jeuno/Shadows_of_the_Departed.lua",["SHA256"]="8c9cb0e549b093d38762c0f696faf14ea1e050a06363172c1c735d7cfaffbd02",["Text"]="-----------------------------------\n-- Shadows of the Departed\n-----------------------------------\n-- Log ID: 3, Quest ID: 88\n-- _0id : !pos 220 -2.5 340 18\n-- _0gc : !pos 100.005 -3.028 -140.005 16\n-- _0k0 : !pos 260 -2.5 180 20\n-----------------------------------\nlocal ruludeID = zones[xi.zone.RULUDE_GARDENS]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.JEUNO, xi.quest.id.jeuno.SHADOWS_OF_THE_DEPARTED)\n\nquest.reward = {}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.JEUNO, xi.quest.id.jeuno.STORMS_OF_FATE) and\n                player:getCurrentMission(xi.mission.log_id.ZILART) == xi.mission.id.zilart.AWAKENING and\n                player:getMissionStatus(xi.mission.log_id.ZILART) == 3 and\n                VanadielUniqueDay() >= vars.Timer\n        end,\n\n        [xi.zone.RULUDE_GARDENS] =\n        {\n            onTriggerAreaEnter =\n            {\n                [1] = function(player, triggerArea)\n                    return quest:progressEvent(161)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [161] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.NOTE_WRITTEN_BY_ESHANTARL)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.PROMYVION_DEM] =\n        {\n            ['_0id'] =\n            {\n                onTrigger = function(player, npc)\n                    if not player:hasKeyItem(xi.keyItem.PROMYVION_DEM_SLIVER) then\n                        return quest:keyItem(xi.keyItem.PROMYVION_DEM_SLIVER)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.PROMYVION_HOLLA] =\n        {\n            ['_0gc'] =\n            {\n                onTrigger = function(player, npc)\n                    if not player:hasKeyItem(xi.keyItem.PROMYVION_HOLLA_SLIVER) then\n                        return quest:keyItem(xi.keyItem.PROMYVION_HOLLA_SLIVER)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.PROMYVION_MEA] =\n        {\n            ['_0k0'] =\n            {\n                onTrigger = function(player, npc)\n                    if not player:hasKeyItem(xi.keyItem.PROMYVION_MEA_SLIVER) then\n                        return quest:keyItem(xi.keyItem.PROMYVION_MEA_SLIVER)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.RULUDE_GARDENS] =\n        {\n            onTriggerAreaEnter =\n            {\n                [1] = function(player, triggerArea)\n                    for keyItemId = xi.keyItem.PROMYVION_HOLLA_SLIVER, xi.keyItem.PROMYVION_HOLLA_SLIVER + 2 do\n                        if not player:hasKeyItem(keyItemId) then\n                            return\n                        end\n                    end\n\n                    return quest:progressEvent(162)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [162] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        for keyItemId = xi.keyItem.PROMYVION_HOLLA_SLIVER, xi.keyItem.PROMYVION_HOLLA_SLIVER + 2 do\n                            player:delKeyItem(keyItemId)\n                        end\n\n                        player:messageSpecial(ruludeID.text.YOU_HAND_THE_THREE_SLIVERS)\n\n                        xi.quest.setVar(player, xi.questLog.JEUNO, xi.quest.id.jeuno.APOCALYPSE_NIGH, 'Timer', VanadielUniqueDay() + 1)\n                        xi.quest.setMustZone(player, xi.questLog.JEUNO, xi.quest.id.jeuno.APOCALYPSE_NIGH)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/jeuno/Storms_of_Fate.lua"]={["Path"]="scripts/quests/jeuno/Storms_of_Fate.lua",["SHA256"]="0530725fa5c9c6c86da564bf3fdb12738d38cd1775e899f1cd2d1ea8fbda50e8",["Text"]="-----------------------------------\n-- Storms of Fate\n-----------------------------------\n-- Log ID: 3, Quest ID: 86\n-- _0p2                  : !pos -259 -30 276 25\n-- Unstable_Displacement : !pos -612.800 1.750 693.190 29\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.JEUNO, xi.quest.id.jeuno.STORMS_OF_FATE)\n\nquest.reward = {}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getCurrentMission(xi.mission.log_id.COP) == xi.mission.id.cop.DAWN and\n                xi.mission.getVar(player, xi.mission.log_id.COP, xi.mission.id.cop.DAWN, 'Status') == 8 and\n                not quest:getMustZone(player)\n        end,\n\n        [xi.zone.RULUDE_GARDENS] =\n        {\n            onTriggerAreaEnter =\n            {\n                [1] = function(player, triggerArea)\n                    return quest:progressEvent(142)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [142] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:begin(player)\n                    else\n                        -- TODO: There may be an alternate event or parameters passed if this quest was\n                        -- initially declined.  This mustZone is a placeholder only, and needs verification.\n\n                        quest:setMustZone(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.MISAREAUX_COAST] =\n        {\n            ['_0p2'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 0 then\n                        return quest:progressEvent(559)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [559] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n        },\n\n        [xi.zone.RIVERNE_SITE_B01] =\n        {\n            ['Unstable_Displacement'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 1 then\n                        return quest:progressEvent(1)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [1] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n\n                [32001] = function(player, csid, option, npc)\n                    if\n                        player:getLocalVar('battlefieldWin') == xi.battlefield.id.STORMS_OF_FATE and\n                        quest:getVar(player, 'Prog') == 2\n                    then\n                        npcUtil.giveKeyItem(player, xi.keyItem.WHISPER_OF_THE_WYRMKING)\n                        quest:setVar(player, 'Prog', 3)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.RULUDE_GARDENS] =\n        {\n            onTriggerAreaEnter =\n            {\n                [1] = function(player, triggerArea)\n                    if quest:getVar(player, 'Prog') == 3 then\n                        return quest:progressEvent(143)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [143] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        xi.quest.setVar(player, xi.questLog.JEUNO, xi.quest.id.jeuno.SHADOWS_OF_THE_DEPARTED, 'Timer', VanadielUniqueDay() + 1)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/jeuno/Tenshodo_Membership.lua"]={["Path"]="scripts/quests/jeuno/Tenshodo_Membership.lua",["SHA256"]="26ad42750613ab4a9dbb69b66af0bf192714cb5295654395ba85b4542983928f",["Text"]="-----------------------------------\n-- Tenshodo Membership\n-----------------------------------\n-- Log ID: 3, Quest ID: 17\n-- NPC: Ghebi Damomohe !pos 16 -.1 -5.2 245\n-- NPC: Jabbar !pos -101 -2.3 23 236\n-- NOTE: Players can straight turn in Tenshodo Invite bypassing this quest. Quest never shows in log until completed.\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.JEUNO, xi.quest.id.jeuno.TENSHODO_MEMBERSHIP)\n\nquest.reward =\n{\n    item    = xi.item.TENSHODO_INVITE,\n    keyItem = xi.keyItem.TENSHODO_MEMBERS_CARD,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.LOWER_JEUNO] =\n        {\n            ['Ghebi_Damomohe'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeMatches(trade, { { xi.item.TENSHODO_INVITE, 1 } }) then\n                        return quest:progressEvent(108)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    if player:getFameLevel(xi.fameArea.JEUNO) >= 3 then\n                        if player:hasKeyItem(xi.keyItem.TENSHODO_APPLICATION_FORM) then\n                            return quest:progressEvent(107)\n                        else\n                            return quest:event(106)\n                        end\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [106] = function(player, csid, option, npc)\n                    if option == 2 then\n                        quest:setVar(player, 'Prog', 1)\n                    end\n                end,\n\n                [107] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.TENSHODO_APPLICATION_FORM)\n                    end\n                end,\n\n                [108] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:tradeComplete()\n                        player:delKeyItem(xi.keyItem.TENSHODO_APPLICATION_FORM)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Jabbar'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.TENSHODO_APPLICATION_FORM) then\n                        return quest:progressEvent(152)\n                    elseif quest:getVar(player, 'Prog') == 1 then\n                        return quest:progressEvent(151)\n                    end\n                end,\n            },\n\n            ['Silver_Owl'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.TENSHODO_APPLICATION_FORM) then\n                        return quest:progressEvent(152, 1)\n                    elseif quest:getVar(player, 'Prog') == 1 then\n                        return quest:progressEvent(151, 1)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [151] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.TENSHODO_APPLICATION_FORM)\n                end,\n            },\n        },\n    }\n}\n\nreturn quest\n"},["scripts/quests/jeuno/The_Antique_Collector.lua"]={["Path"]="scripts/quests/jeuno/The_Antique_Collector.lua",["SHA256"]="bf28160b9afc425036056288c2fc4b522144e337182823fdbab6137a2ca87673",["Text"]="-----------------------------------\n-- The Antique Collector\n-----------------------------------\n-- Log ID: 3, Quest ID: 25\n-- Imasuke : !pos -165 11 94 246\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.JEUNO, xi.quest.id.jeuno.THE_ANTIQUE_COLLECTOR)\n\n-- TODO: Quest reward has conflicting information from various resources.  Need to confirm\n-- that XP and Gil rewards are also given when the player does not have the KI reward.\n\nquest.reward =\n{\n    exp      = 2000,\n    gil      = 2000,\n    keyItem  = xi.keyItem.MAP_OF_DELKFUTTS_TOWER,\n    title    = xi.title.TRADER_OF_ANTIQUITIES,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getFameLevel(xi.fameArea.JEUNO) >= 2\n        end,\n\n        [xi.zone.PORT_JEUNO] =\n        {\n            ['Imasuke'] = quest:progressEvent(13),\n\n            onEventFinish =\n            {\n                [13] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.PORT_JEUNO] =\n        {\n            ['Imasuke'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, xi.item.KAISER_SWORD) then\n                        return quest:progressEvent(15)\n                    end\n                end,\n\n                onTrigger = quest:event(14),\n            },\n\n            onEventFinish =\n            {\n                [15] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:addFame(xi.fameArea.SANDORIA, 10)\n                        player:addFame(xi.fameArea.BASTOK, 10)\n                        player:addFame(xi.fameArea.WINDURST, 10)\n                        player:confirmTrade()\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/jeuno/The_Circle_of_Time.lua"]={["Path"]="scripts/quests/jeuno/The_Circle_of_Time.lua",["SHA256"]="b33b6a4a4105893ab088276a39c26b712713133248fd070f1e51f0863285e95f",["Text"]="-----------------------------------\n-- The Circle of Time (BRD AF3)\n-----------------------------------\n-- Log ID: 3, Quest ID: 65\n-- !addquest 3 65\n-- Mertaire       : !pos -17 0 -61 245\n-- Imasuke        : !pos -165 11 96 246\n-- Perennial Snow : !pos 339 0 -379 112\n-- Chalvatot      : !pos -105 0.1 72 233\n-- Altar          : !pos 109 -3 -145 150\n-----------------------------------\n-- Mertaire's hint (event 139) repeats and plays regardless of job; the quest is only granted by Imasuke's appraisal.\n-----------------------------------\nlocal monasticID  = zones[xi.zone.MONASTIC_CAVERN]\nlocal xarcabardID = zones[xi.zone.XARCABARD]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.JEUNO, xi.quest.id.jeuno.THE_CIRCLE_OF_TIME)\n\nquest.reward =\n{\n    item  = xi.item.CHORAL_JUSTAUCORPS,\n    title = xi.title.PARAGON_OF_BARD_EXCELLENCE,\n}\n\nquest.sections =\n{\n    -- Section: Quest is available.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.JEUNO, xi.quest.id.jeuno.THE_REQUIEM)\n        end,\n\n        [xi.zone.LOWER_JEUNO] =\n        {\n            ['Mertaire'] = quest:progressEvent(139),\n\n            onEventFinish =\n            {\n                [139] = function(player, csid, option, npc)\n                    if\n                        option == 0 and\n                        quest:getVar(player, 'Prog') == 0\n                    then\n                        quest:setVar(player, 'Prog', 1)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.PORT_JEUNO] =\n        {\n            ['Imasuke'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        player:getMainJob() ~= xi.job.BRD or\n                        player:getMainLvl() < xi.settings.main.AF3_QUEST_LEVEL\n                    then\n                        return\n                    end\n\n                    local progress = quest:getVar(player, 'Prog')\n\n                    if progress == 1 then\n                        return quest:progressEvent(30)\n                    elseif progress == 2 then\n                        return quest:progressEvent(29) -- Short offer after the player declined once.\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [29] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:begin(player)\n                        quest:setVar(player, 'Prog', 3)\n                    end\n                end,\n\n                [30] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:begin(player)\n                        quest:setVar(player, 'Prog', 3)\n                    elseif option == 0 then\n                        quest:setVar(player, 'Prog', 2) -- Player declined.\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest accepted.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.CHATEAU_DORAGUILLE] =\n        {\n            ['Chalvatot'] =\n            {\n                onTrigger = function(player, npc)\n                    local progress = quest:getVar(player, 'Prog')\n\n                    if progress == 5 then\n                        return quest:progressEvent(99)\n                    elseif progress == 6 then\n                        return quest:progressEvent(98)\n                    elseif progress == 7 then\n                        return quest:event(97) -- Reminder: place the rings upon the altar.\n                    elseif progress == 9 then\n                        return quest:progressEvent(96)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [96] = function(player, csid, option, npc)\n                    if\n                        option == 0 and\n                        quest:complete(player)\n                    then\n                        player:addFame(xi.fameArea.SANDORIA, 7)\n                        player:addFame(xi.fameArea.BASTOK, 7)\n                        player:addFame(xi.fameArea.WINDURST, 7)\n                    end\n                end,\n\n                [98] = function(player, csid, option, npc)\n                    if option == 1 then\n                        npcUtil.giveKeyItem(player, xi.keyItem.MOON_RING)\n                        quest:setVar(player, 'Prog', 7)\n                    end\n                end,\n\n                [99] = function(player, csid, option, npc)\n                    if option == 1 then\n                        npcUtil.giveKeyItem(player, xi.keyItem.MOON_RING)\n                        quest:setVar(player, 'Prog', 7)\n                    elseif option == 0 then\n                        quest:setVar(player, 'Prog', 6)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.MONASTIC_CAVERN] =\n        {\n            ['Altar'] =\n            {\n                onTrigger = function(player, npc)\n                    local progress = quest:getVar(player, 'Prog')\n\n                    if\n                        progress == 7 and\n                        npcUtil.popFromQM(player, npc, monasticID.mob.BUGABOO, { hide = 0 })\n                    then\n                        return quest:noAction() -- No message. Bugaboo spawns and immediately aggroes.\n                    elseif progress == 8 then\n                        return quest:progressEvent(3)\n                    end\n                end,\n            },\n\n            ['Bugaboo'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    if quest:getVar(player, 'Prog') == 7 then\n                        quest:setVar(player, 'Prog', 8)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [3] = function(player, csid, option, npc)\n                    if option == 0 then\n                        player:delKeyItem(xi.keyItem.STAR_RING1)\n                        player:delKeyItem(xi.keyItem.MOON_RING)\n                        quest:setVar(player, 'Prog', 9)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.PORT_JEUNO] =\n        {\n            ['Imasuke'] =\n            {\n                onTrigger = function(player, npc)\n                    local progress = quest:getVar(player, 'Prog')\n\n                    if progress == 3 then\n                        return quest:event(32) -- Reminder: bury the ring in Xarcabard.\n                    elseif progress == 4 then\n                        return quest:progressEvent(33)\n                    elseif progress == 5 then\n                        return quest:event(31) -- Reminder: take the ring to Chateau d'Oraguille.\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [33] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:setVar(player, 'Prog', 5)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.XARCABARD] =\n        {\n            ['Perennial_Snow'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') ~= 3 then\n                        return\n                    end\n\n                    local purifiedTime = quest:getVar(player, 'Buried')\n\n                    if purifiedTime == 0 then\n                        return quest:progressEvent(3)\n                    elseif GetSystemTime() >= purifiedTime then\n                        return quest:progressEvent(2)\n                    else\n                        return quest:messageSpecial(xarcabardID.text.PERENNIAL_SNOW_WAIT, xi.keyItem.STAR_RING1)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [2] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:setVar(player, 'Prog', 4)\n                    end\n                end,\n\n                [3] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:setVar(player, 'Buried', GetSystemTime() + 30) -- Capture: the buried ring was purified within 35 seconds.\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/jeuno/The_Clockmaster.lua"]={["Path"]="scripts/quests/jeuno/The_Clockmaster.lua",["SHA256"]="5a26378132de6cf5b0723769d413f310cb11160ad2d7d5e7c6dcc3cd743c417b",["Text"]="-----------------------------------\n-- The Clockmaster\n-----------------------------------\n-- Log ID: 3, Quest ID: 21\n-- _6s2   : !pos -80 0 104 244\n-- Collet : !pos -44 0 107 244\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.JEUNO, xi.quest.id.jeuno.THE_CLOCKMASTER)\n\nquest.reward =\n{\n    item     = xi.item.TIME_HAMMER,\n    gil      = 1200,\n    title    = xi.title.TIMEKEEPER,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.JEUNO, xi.quest.id.jeuno.SAVE_THE_CLOCK_TOWER) and\n                player:getFameLevel(xi.fameArea.JEUNO) >= 5\n        end,\n\n        [xi.zone.UPPER_JEUNO] =\n        {\n            ['_6s2'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(152)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [152] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:addFame(xi.fameArea.SANDORIA, 17)\n                        player:addFame(xi.fameArea.BASTOK, 17)\n                        player:addFame(xi.fameArea.WINDURST, 17)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.UPPER_JEUNO] =\n        {\n            ['_6s2']   = quest:event(110):replaceDefault(),\n            ['Collet'] = quest:event(163):replaceDefault(),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/jeuno/The_Gobbiebag_Part_I.lua"]={["Path"]="scripts/quests/jeuno/The_Gobbiebag_Part_I.lua",["SHA256"]="4d8ace6bdba65cbc25016816a45448f2cfab48351c983359c324e77098cfb2d8",["Text"]="-----------------------------------\n-- The Gobbiebag Part I\n-----------------------------------\n--  Log ID: 3, Quest ID: 27\n--  NPC: Bluffnix:  !pos -43 6 -115 245\n-----------------------------------\nrequire('scripts/quests/jeuno/helpers')\n-----------------------------------\nlocal lowerJeunoID = zones[xi.zone.LOWER_JEUNO]\n-----------------------------------\n\nlocal params =\n{\n    questId            = xi.quest.id.jeuno.THE_GOBBIEBAG_PART_I,\n    prerequisite       = nil,\n    message            = lowerJeunoID.text.INVENTORY_INCREASED,\n    startInventorySize = 30,\n    fame               = 1,\n    tradeStew          = xi.item.BOWL_OF_GOBLIN_STEW_880,\n\n    tradeItems =\n    {\n        xi.item.SQUARE_OF_DHALMEL_LEATHER,\n        xi.item.STEEL_INGOT,\n        xi.item.SQUARE_OF_LINEN_CLOTH,\n        xi.item.PERIDOT,\n    },\n\n    reward =\n    {\n        title = nil,\n    },\n}\n\nlocal quest = xi.jeuno.helpers.GobbiebagQuest:new(params)\n\nreturn quest\n"},["scripts/quests/jeuno/The_Gobbiebag_Part_II.lua"]={["Path"]="scripts/quests/jeuno/The_Gobbiebag_Part_II.lua",["SHA256"]="4dadaa144ca9f78d74ef1dd2003050d05e283fc3a506ff0d0f89a146c7275d6a",["Text"]="-----------------------------------\n-- The Gobbiebag Part II\n-----------------------------------\n--  Log ID: 3, Quest ID: 27\n--  NPC: Bluffnix:  !pos -43 6 -115 245\n-----------------------------------\nrequire('scripts/quests/jeuno/helpers')\n-----------------------------------\nlocal lowerJeunoID = zones[xi.zone.LOWER_JEUNO]\n-----------------------------------\n\nlocal params =\n{\n    questId            = xi.quest.id.jeuno.THE_GOBBIEBAG_PART_II,\n    prerequisite       = xi.quest.id.jeuno.THE_GOBBIEBAG_PART_I,\n    message            = lowerJeunoID.text.INVENTORY_INCREASED,\n    startInventorySize = 35,\n    fame               = 1,\n    tradeStew          = xi.item.BOWL_OF_GOBLIN_STEW_880,\n\n    tradeItems =\n    {\n        xi.item.SQUARE_OF_RAM_LEATHER,\n        xi.item.MYTHRIL_INGOT,\n        xi.item.SQUARE_OF_WOOL_CLOTH,\n        xi.item.TURQUOISE,\n    },\n\n    reward =\n    {\n        title = nil,\n    },\n}\n\nlocal quest = xi.jeuno.helpers.GobbiebagQuest:new(params)\n\nreturn quest\n"},["scripts/quests/jeuno/The_Gobbiebag_Part_III.lua"]={["Path"]="scripts/quests/jeuno/The_Gobbiebag_Part_III.lua",["SHA256"]="d5f924217eca14e7f19ebe0c5b56db758d0507092d6b71df9dbbfed4c8671099",["Text"]="-----------------------------------\n-- The Gobbiebag Part III\n-----------------------------------\n--  Log ID: 3, Quest ID: 27\n--  NPC: Bluffnix:  !pos -43 6 -115 245\n-----------------------------------\nrequire('scripts/quests/jeuno/helpers')\n-----------------------------------\nlocal lowerJeunoID = zones[xi.zone.LOWER_JEUNO]\n-----------------------------------\n\nlocal params =\n{\n    questId            = xi.quest.id.jeuno.THE_GOBBIEBAG_PART_III,\n    prerequisite       = xi.quest.id.jeuno.THE_GOBBIEBAG_PART_II,\n    message            = lowerJeunoID.text.INVEN