      title = xi.title.GREEDALOX,\n    },\n}\n\nlocal quest = xi.jeuno.helpers.GobbiebagQuest:new(params)\n\nreturn quest\n"},["scripts/quests/jeuno/The_Gobbiebag_Part_VI.lua"]={["Path"]="scripts/quests/jeuno/The_Gobbiebag_Part_VI.lua",["SHA256"]="da2d4a3ff7a17fe2e492bfb55ec63ec2aa406c0eca505905655b777041c426dc",["Text"]="-----------------------------------\n-- The Gobbiebag Part VI\n-----------------------------------\n--  Log ID: 3, Quest ID: 27\n--  NPC: Bluffnix:  !pos -43 6 -115 245\n-----------------------------------\nrequire('scripts/quests/jeuno/helpers')\n-----------------------------------\nlocal lowerJeunoID = zones[xi.zone.LOWER_JEUNO]\n-----------------------------------\n\nlocal params =\n{\n    questId            = xi.quest.id.jeuno.THE_GOBBIEBAG_PART_VI,\n    prerequisite       = xi.quest.id.jeuno.THE_GOBBIEBAG_PART_V,\n    message            = lowerJeunoID.text.INVENTORY_INCREASED,\n    startInventorySize = 55,\n    fame               = 3,\n    tradeStew          = xi.item.BOWL_OF_GOBLIN_STEW_880,\n\n    tradeItems =\n    {\n        xi.item.SHAKUDO_INGOT,\n        xi.item.SQUARE_OF_BALLON_CLOTH,\n        xi.item.IOLITE,\n        xi.item.HIGH_QUALITY_EFT_SKIN,\n    },\n\n    reward =\n    {\n        title = nil,\n    },\n}\n\nlocal quest = xi.jeuno.helpers.GobbiebagQuest:new(params)\n\nreturn quest\n"},["scripts/quests/jeuno/The_Gobbiebag_Part_VII.lua"]={["Path"]="scripts/quests/jeuno/The_Gobbiebag_Part_VII.lua",["SHA256"]="dc8ca353f2f8ca3d6782753c31250700fbde3bd33aec76ad400da7eb3dbc1aa8",["Text"]="-----------------------------------\n-- The Gobbiebag Part VII\n-----------------------------------\n--  Log ID: 3, Quest ID: 27\n--  NPC: Bluffnix:  !pos -43 6 -115 245\n-----------------------------------\nrequire('scripts/quests/jeuno/helpers')\n-----------------------------------\nlocal lowerJeunoID = zones[xi.zone.LOWER_JEUNO]\n-----------------------------------\n\nlocal params =\n{\n    questId            = xi.quest.id.jeuno.THE_GOBBIEBAG_PART_VII,\n    prerequisite       = xi.quest.id.jeuno.THE_GOBBIEBAG_PART_VI,\n    message            = lowerJeunoID.text.INVENTORY_INCREASED,\n    startInventorySize = 60,\n    fame               = 4,\n    tradeStew          = xi.item.BOWL_OF_GOBLIN_STEW_880,\n\n    tradeItems =\n    {\n        xi.item.SQUARE_OF_LYNX_LEATHER,\n        xi.item.ADAMAN_INGOT,\n        xi.item.SQUARE_OF_RAINBOW_CLOTH,\n        xi.item.DEATHSTONE,\n    },\n\n    reward =\n    {\n        title = nil,\n    },\n}\n\nlocal quest = xi.jeuno.helpers.GobbiebagQuest:new(params)\n\nreturn quest\n"},["scripts/quests/jeuno/The_Gobbiebag_Part_VIII.lua"]={["Path"]="scripts/quests/jeuno/The_Gobbiebag_Part_VIII.lua",["SHA256"]="cdd0314d646a6943c6d4ca19ffaea6ceffcf9697acebff4ba091170e03bdf28d",["Text"]="-----------------------------------\n-- The Gobbiebag Part VIII\n-----------------------------------\n--  Log ID: 3, Quest ID: 27\n--  NPC: Bluffnix:  !pos -43 6 -115 245\n-----------------------------------\nrequire('scripts/quests/jeuno/helpers')\n-----------------------------------\nlocal lowerJeunoID = zones[xi.zone.LOWER_JEUNO]\n-----------------------------------\n\nlocal params =\n{\n    questId            = xi.quest.id.jeuno.THE_GOBBIEBAG_PART_VIII,\n    prerequisite       = xi.quest.id.jeuno.THE_GOBBIEBAG_PART_VII,\n    message            = lowerJeunoID.text.INVENTORY_INCREASED,\n    startInventorySize = 65,\n    fame               = 4,\n    tradeStew          = xi.item.BOWL_OF_GOBLIN_STEW_880,\n\n    tradeItems =\n    {\n        xi.item.SQUARE_OF_SMILODON_LEATHER,\n        xi.item.ELECTRUM_INGOT,\n        xi.item.SQUARE_OF_CILICE,\n        xi.item.ANGELSTONE,\n    },\n\n    reward =\n    {\n        title = nil,\n    },\n}\n\nlocal quest = xi.jeuno.helpers.GobbiebagQuest:new(params)\n\nreturn quest\n"},["scripts/quests/jeuno/The_Gobbiebag_Part_X.lua"]={["Path"]="scripts/quests/jeuno/The_Gobbiebag_Part_X.lua",["SHA256"]="d6cd55444d5a2434757bb94f880abbbe5127b62727cac004913269869a51404d",["Text"]="-----------------------------------\n-- The Gobbiebag Part X\n-----------------------------------\n--  Log ID: 3, Quest ID: 27\n--  NPC: Bluffnix:  !pos -43 6 -115 245\n-----------------------------------\nrequire('scripts/quests/jeuno/helpers')\n-----------------------------------\nlocal lowerJeunoID = zones[xi.zone.LOWER_JEUNO]\n-----------------------------------\n\nlocal params =\n{\n    questId            = xi.quest.id.jeuno.THE_GOBBIEBAG_PART_X,\n    prerequisite       = xi.quest.id.jeuno.THE_GOBBIEBAG_PART_IX,\n    message            = lowerJeunoID.text.INVENTORY_INCREASED,\n    startInventorySize = 75,\n    fame               = 5,\n    tradeStew          = xi.item.BOWL_OF_GOBLIN_STEW_880,\n\n    tradeItems =\n    {\n        xi.item.MOLYBDENUM_INGOT,\n        xi.item.SQUARE_OF_GRIFFON_LEATHER,\n        xi.item.SQUARE_OF_FOULARD,\n        xi.item.ANGEL_SKIN_ORB,\n    },\n\n    reward =\n    {\n        title = xi.title.GRAND_GREEDALOX,\n    },\n}\n\nlocal quest = xi.jeuno.helpers.GobbiebagQuest:new(params)\n\nreturn quest\n"},["scripts/quests/jeuno/The_Goblin_Tailor.lua"]={["Path"]="scripts/quests/jeuno/The_Goblin_Tailor.lua",["SHA256"]="02bb195c2c9ea575d165420f7d6f2c73f0e8d53daacffe5928055448733fc0c0",["Text"]="-----------------------------------\n-- The Goblin Tailor\n-----------------------------------\n-- Log ID: 3, Quest ID: 42\n-- Guttrix : !pos -36.010 4.499 -139.714 245\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.JEUNO, xi.quest.id.jeuno.THE_GOBLIN_TAILOR)\n\nlocal rseTable =\n{\n    -- [race] = { body, hands, legs, feet }\n    [xi.race.HUME_M  ] = { xi.item.CUSTOM_TUNIC,     xi.item.CUSTOM_M_GLOVES,  xi.item.CUSTOM_SLACKS,    xi.item.CUSTOM_M_BOOTS    },\n    [xi.race.HUME_F  ] = { xi.item.CUSTOM_VEST,      xi.item.CUSTOM_F_GLOVES,  xi.item.CUSTOM_PANTS,     xi.item.CUSTOM_F_BOOTS    },\n    [xi.race.ELVAAN_M] = { xi.item.MAGNA_JERKIN,     xi.item.MAGNA_GAUNTLETS,  xi.item.MAGNA_M_CHAUSSES, xi.item.MAGNA_M_LEDELSENS },\n    [xi.race.ELVAAN_F] = { xi.item.MAGNA_BODICE,     xi.item.MAGNA_GLOVES,     xi.item.MAGNA_F_CHAUSSES, xi.item.MAGNA_F_LEDELSENS },\n    [xi.race.TARU_M  ] = { xi.item.WONDER_KAFTAN,    xi.item.WONDER_MITTS,     xi.item.WONDER_BRACCAE,   xi.item.WONDER_CLOMPS     },\n    [xi.race.TARU_F  ] = { xi.item.WONDER_KAFTAN,    xi.item.WONDER_MITTS,     xi.item.WONDER_BRACCAE,   xi.item.WONDER_CLOMPS     },\n    [xi.race.MITHRA  ] = { xi.item.SAVAGE_SEPARATES, xi.item.SAVAGE_GAUNTLETS, xi.item.SAVAGE_LOINCLOTH, xi.item.SAVAGE_GAITERS    },\n    [xi.race.GALKA   ] = { xi.item.ELDERS_SURCOAT,   xi.item.ELDERS_BRACERS,   xi.item.ELDERS_BRAGUETTE, xi.item.ELDERS_SANDALS    },\n}\n\nquest.reward =\n{\n    title = xi.title.GOBLINS_EXCLUSIVE_FASHION_MANNEQUIN,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.LOWER_JEUNO] =\n        {\n            ['Guttrix'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        player:getMainLvl() >= 10 and\n                        player:getFameLevel(xi.fameArea.JEUNO) >= 3\n                    then\n                        return quest:progressEvent(10016, VanadielRSELocation(), VanadielRSERace())\n                    else\n                        return quest:event(10020)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [10016] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status >= xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.GUSGEN_MINES] =\n        {\n            ['Treasure_Chest' ] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        VanadielRSELocation() == 1 and\n                        VanadielRSERace() == player:getRace() and\n                        not player:hasKeyItem(xi.keyItem.MAGICAL_PATTERN)\n                    then\n                        xi.treasure.onTrade(player, npc, trade, 2, xi.keyItem.MAGICAL_PATTERN)\n\n                        return quest:noAction()\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.LOWER_JEUNO] =\n        {\n            ['Guttrix'] =\n            {\n                onTrigger = function(player, npc)\n                    local rseTracker = player:getCharVar('[RSE]Gear')\n                    if rseTracker == 15 then\n                        return quest:event(10019)\n                    end\n\n                    if player:getMainLvl() < 10 then\n                        return quest:event(10020)\n                    end\n\n                    if player:hasKeyItem(xi.keyItem.MAGICAL_PATTERN) then\n                        return quest:progressEvent(10018, rseTracker)\n                    else\n                        return quest:event(10017, VanadielRSELocation(), VanadielRSERace())\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [10018] = function(player, csid, option, npc)\n                    if not player:hasKeyItem(xi.keyItem.MAGICAL_PATTERN) then\n                        return\n                    end\n\n                    if option < 1 then\n                        return\n                    end\n\n                    if option > 4 then\n                        return\n                    end\n\n                    local rseTracker = player:getCharVar('[RSE]Gear')\n                    if utils.mask.getBit(rseTracker, option - 1) then\n                        return\n                    end\n\n                    if npcUtil.giveItem(player, rseTable[player:getRace()][option]) then\n                        player:delKeyItem(xi.keyItem.MAGICAL_PATTERN)\n                        player:incrementCharVar('[RSE]Gear', bit.lshift(1, option - 1))\n\n                        quest:complete(player)\n                        player:addFame(xi.fameArea.SANDORIA, 5)\n                        player:addFame(xi.fameArea.BASTOK, 5)\n                        player:addFame(xi.fameArea.WINDURST, 5)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.MAZE_OF_SHAKHRAMI] =\n        {\n            ['Treasure_Chest' ] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        VanadielRSELocation() == 2 and\n                        VanadielRSERace() == player:getRace() and\n                        not player:hasKeyItem(xi.keyItem.MAGICAL_PATTERN)\n                    then\n                        xi.treasure.onTrade(player, npc, trade, 2, xi.keyItem.MAGICAL_PATTERN)\n\n                        return quest:noAction()\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.ORDELLES_CAVES] =\n        {\n            ['Treasure_Chest' ] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        VanadielRSELocation() == 0 and\n                        VanadielRSERace() == player:getRace() and\n                        not player:hasKeyItem(xi.keyItem.MAGICAL_PATTERN)\n                    then\n                        xi.treasure.onTrade(player, npc, trade, 2, xi.keyItem.MAGICAL_PATTERN)\n\n                        return quest:noAction()\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"}};
